1	import { Injectable } from '@angular/core';
2	
3	export const QUOTE_SESSION_KEY = 'quote-session';
4	
5	export type Step1Values = Record<string, string | boolean>;
6	
7	export interface QuoteSession {
8	  countryCode: string;
9	  data: Record<string, unknown>;
10	}
11	
12	/** Single persistence helper for the quote wizard (sessionStorage). Never stores tokens. */
13	@Injectable({ providedIn: 'root' })
14	export class QuoteSessionStore {
15	  read(): QuoteSession | null {
16	    try {
17	      const raw = sessionStorage.getItem(QUOTE_SESSION_KEY);
18	      if (!raw) return null;
19	      const parsed: unknown = JSON.parse(raw);
20	      if (typeof parsed !== 'object' || parsed === null) return null;
21	      const { countryCode, data } = parsed as Partial<QuoteSession>;
22	      if (typeof countryCode !== 'string' || !countryCode) return null;
23	      const safeData =
24	        typeof data === 'object' && data !== null && !Array.isArray(data) ? data : {};
25	      return { countryCode, data: safeData };
26	    } catch {
27	      return null;
28	    }
29	  }
30	
31	  lastCountryCode(): string | null {
32	    return this.read()?.countryCode ?? null;
33	  }
34	
35	  /** True only when step 1 holds a non-empty string (trimmed) or a checked box. */
36	  hasData(): boolean {
37	    return Object.values(this.readStep1()).some(
38	      (value) => value === true || (typeof value === 'string' && value.trim() !== ''),
39	    );
40	  }
41	
42	  readStep1(): Step1Values {
43	    const raw = this.read()?.data['step1'];
44	    if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) return {};
45	    const values: Step1Values = {};
46	    for (const [key, value] of Object.entries(raw)) {
47	      if (typeof value === 'string' || typeof value === 'boolean') values[key] = value;
48	    }
49	    return values;
50	  }
51	
52	  /** Saves step 1 values; any earlier completion no longer applies. */
53	  saveStep1(values: Step1Values): void {
54	    const current = this.read();
55	    if (!current) return;
56	    const rest = { ...current.data };
57	    delete rest['step1Completed'];
58	    this.write({ countryCode: current.countryCode, data: { ...rest, step1: { ...values } } });
59	  }
60	
61	  markStep1Completed(): void {
62	    const current = this.read();
63	    if (!current) return;
64	    this.write({
65	      countryCode: current.countryCode,
66	      data: { ...current.data, step1Completed: true },
67	    });
68	  }
69	
70	  isStep1Completed(): boolean {
71	    return this.read()?.data['step1Completed'] === true;
72	  }
73	
74	  /** Same country keeps data; a different country resets it. */
75	  start(countryCode: string): void {
76	    const current = this.read();
77	    const data = current?.countryCode === countryCode ? current.data : {};
78	    this.write({ countryCode, data });
79	  }
80	
81	  /** Keeps the country, empties the form data. */
82	  discardData(): void {
83	    const current = this.read();
84	    if (current) this.write({ countryCode: current.countryCode, data: {} });
85	  }
86	
87	  clear(): void {
88	    try {
89	      sessionStorage.removeItem(QUOTE_SESSION_KEY);
90	    } catch {
91	      /* storage unavailable */
92	    }
93	  }
94	
95	  private write(session: QuoteSession): void {
96	    try {
97	      sessionStorage.setItem(QUOTE_SESSION_KEY, JSON.stringify(session));
98	    } catch {
99	      /* storage unavailable: degrade to no persistence */
100	    }
101	  }
102	}
