7	describe('US-00 · FR-001 country mapper', () => {
8	  it('lower-cases the code', () => {
9	    expect(mapCountry(base).code).toBe('co');
10	  });
11	
12	  it('maps icon url and alternative text', () => {
13	    const country = mapCountry({
14	      ...base,
15	      icon: { id: 1, documentId: 'x', url: '/uploads/co.svg', alternativeText: 'Bandera de Colombia' },
