22	    const country = mapCountry(base);
23	    expect(country.iconUrl).toBeNull();
24	    expect(country.iconAlt).toBe('Colombia');
25	  });
26	
27	  it('falls back to the name when alternativeText is null', () => {
28	    const country = mapCountry({
29	      ...base,
30	      icon: { id: 1, documentId: 'x', url: '/u.svg', alternativeText: null },
31	    });
32	    expect(country.iconAlt).toBe('Colombia');
33	  });
34	});
