49	describe('US-01 · FR-007 country legal age', () => {
50	  it('maps the legal age from the CMS', () => {
51	    expect(mapCountry({ ...base, legalAge: 21 }).legalAge).toBe(21);
52	  });
53	
54	  it('defaults to 18 when null, missing or negative', () => {
55	    expect(mapCountry({ ...base, legalAge: null }).legalAge).toBe(18);
56	    const withoutAge: Partial<CountryDto> = { ...base };
57	    delete withoutAge.legalAge;
