7	describe('US-00 · FR-011 / FR-012 quote session store', () => {
8	  let store: QuoteSessionStore;
9	
10	  beforeEach(() => {
11	    sessionStorage.clear();
12	    store = new QuoteSessionStore();
13	  });
14	
15	  it('returns null when nothing is stored', () => {
16	    expect(store.read()).toBeNull();
17	    expect(store.lastCountryCode()).toBeNull();
18	    expect(store.hasData()).toBe(false);
19	  });
20	
21	  it('treats corrupt JSON as no session', () => {
22	    sessionStorage.setItem(QUOTE_SESSION_KEY, '{not json');
23	    expect(store.read()).toBeNull();
24	    expect(store.hasData()).toBe(false);
25	  });
26	
27	  it('treats a malformed shape as no session', () => {
28	    seed({ data: {} });
29	    expect(store.read()).toBeNull();
30	  });
31	
32	  // hasData now means "step 1 has user input" (US-01 FR-009), not "data has any key".
33	  it('hasData is true only when step 1 has user input', () => {
34	    seed({ countryCode: 'co', data: {} });
35	    expect(store.hasData()).toBe(false);
36	    seed({ countryCode: 'co', data: { step1: { plate: 'ABC123' } } });
37	    expect(store.hasData()).toBe(true);
38	  });
39	
40	  it('start with the same country keeps the data (FR-011)', () => {
41	    seed({ countryCode: 'co', data: { step1: { plate: 'ABC123' } } });
42	    store.start('co');
43	    expect(store.read()?.data).toEqual({ step1: { plate: 'ABC123' } });
44	  });
45	
46	  it('start with a different country resets the data (FR-012)', () => {
47	    seed({ countryCode: 'co', data: { step1: { plate: 'ABC123' } } });
48	    store.start('cl');
49	    expect(store.read()).toEqual({ countryCode: 'cl', data: {} });
50	  });
51	
52	  it('discardData keeps the country and empties data', () => {
53	    seed({ countryCode: 'co', data: { step1: { plate: 'ABC123' } } });
54	    store.discardData();
55	    expect(store.read()).toEqual({ countryCode: 'co', data: {} });
56	  });
57	
58	  it('clear removes the session', () => {
59	    seed({ countryCode: 'co', data: { a: 1 } });
60	    store.clear();
61	    expect(store.read()).toBeNull();
62	  });
63	});
64	
65	describe('US-01 · FR-009 step 1 persistence', () => {
66	  let store: QuoteSessionStore;
67	
68	  beforeEach(() => {
69	    sessionStorage.clear();
70	    store = new QuoteSessionStore();
71	    store.start('co');
72	  });
73	
74	  it('saves and restores step 1 values', () => {
75	    store.saveStep1({ name: 'Ana', accepted: true });
76	    expect(new QuoteSessionStore().readStep1()).toEqual({ name: 'Ana', accepted: true });
77	  });
78	
79	  it('hasData is false when all values are empty or unchecked', () => {
80	    store.saveStep1({ name: '  ', plate: '', accepted: false });
81	    expect(store.hasData()).toBe(false);
82	  });
83	
84	  it('hasData is true for a checked box or a non-blank string', () => {
85	    store.saveStep1({ accepted: true });
86	    expect(store.hasData()).toBe(true);
87	    store.saveStep1({ name: 'Ana' });
88	    expect(store.hasData()).toBe(true);
89	  });
90	
91	  it('markStep1Completed sets the flag and saveStep1 clears it', () => {
92	    expect(store.isStep1Completed()).toBe(false);
93	    store.markStep1Completed();
94	    expect(store.isStep1Completed()).toBe(true);
95	    store.saveStep1({ name: 'Ana' });
96	    expect(store.isStep1Completed()).toBe(false);
97	  });
98	
99	  it('discardData clears step 1 and completion but keeps the country', () => {
100	    store.saveStep1({ name: 'Ana' });
101	    store.markStep1Completed();
102	    store.discardData();
103	    expect(store.readStep1()).toEqual({});
104	    expect(store.isStep1Completed()).toBe(false);
105	    expect(store.lastCountryCode()).toBe('co');
106	  });
107	
108	  it('is tolerant to corrupt data', () => {
109	    seed({ countryCode: 'co', data: { step1: 'oops', step1Completed: 'yes' } });
110	    expect(store.readStep1()).toEqual({});
111	    expect(store.isStep1Completed()).toBe(false);
112	    seed({ countryCode: 'co', data: { step1: { a: 1, b: 'ok', c: null } } });
113	    expect(store.readStep1()).toEqual({ b: 'ok' });
114	    sessionStorage.setItem(QUOTE_SESSION_KEY, '{bad');
115	    expect(store.readStep1()).toEqual({});
116	    expect(() => store.saveStep1({ a: 'x' })).not.toThrow();
117	  });
118	});
