1	import { ValidationContext } from './validation.model';
2	
3	export type NamedRuleFactory = (
4	  value: number | null,
5	  ctx: ValidationContext,
6	) => (raw: string) => boolean;
7	
8	/** Chilean RUT check-digit validation (modulo 11). */
9	export function isValidRut(raw: string): boolean {
10	  const clean = raw.replace(/[.\s-]/g, '').toUpperCase();
11	  const match = /^(\d{7,8})([0-9K])$/.exec(clean);
12	  if (!match) return false;
13	  const body = match[1];
14	  let sum = 0;
15	  let weight = 2;
16	  for (let i = body.length - 1; i >= 0; i--) {
17	    sum += Number(body[i]) * weight;
18	    weight = weight === 7 ? 2 : weight + 1;
19	  }
20	  const rest = 11 - (sum % 11);
21	  const expected = rest === 11 ? '0' : rest === 10 ? 'K' : String(rest);
22	  return match[2] === expected;
23	}
24	
25	/** raw is yyyy-mm-dd; age computed from local date components. */
26	export function isOfLegalAge(raw: string, legalAge: number, today: Date): boolean {
27	  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(raw);
28	  if (!match) return false;
29	  const y = Number(match[1]);
30	  const m = Number(match[2]);
31	  const d = Number(match[3]);
32	  const birth = new Date(y, m - 1, d);
33	  if (birth.getFullYear() !== y || birth.getMonth() !== m - 1 || birth.getDate() !== d) {
34	    return false;
35	  }
36	  const t = new Date(today.getFullYear(), today.getMonth(), today.getDate());
37	  if (birth.getTime() > t.getTime()) return false;
38	  let age = t.getFullYear() - y;
39	  if (t.getMonth() + 1 < m || (t.getMonth() + 1 === m && t.getDate() < d)) age--;
40	  return age >= legalAge;
41	}
42	
43	function parseYear(raw: string): number | null {
44	  const s = raw.trim();
45	  return /^\d{1,4}$/.test(s) ? Number(s) : null;
46	}
47	
48	export const NAMED_RULES: Record<string, NamedRuleFactory> = {
49	  rut: () => (raw) => isValidRut(raw),
50	  legalAge: (_value, ctx) => (raw) => isOfLegalAge(raw, ctx.legalAge, ctx.today),
51	  maxYearsAgo: (value, ctx) => (raw) => {
52	    const year = parseYear(raw);
53	    return year !== null && value !== null && year >= ctx.today.getFullYear() - value;
54	  },
55	  maxYearsAhead: (value, ctx) => (raw) => {
56	    const year = parseYear(raw);
57	    return year !== null && value !== null && year <= ctx.today.getFullYear() + value;
58	  },
59	};
