import { AgeBand, Country } from '../../../core/country/country.model';

/** First band with fromAge <= age <= toAge gives its factor; no band or unknown age gives 1. */
function factorFor(age: number | null, bands: AgeBand[]): number {
  if (age === null) return 1;
  return bands.find((band) => band.fromAge <= age && age <= band.toAge)?.factor ?? 1;
}

/**
 * Simulated monthly price:
 * `Math.round(basePrice × driverAgeFactor × vehicleAgeFactor)`.
 *
 * Each factor is the first band of the country (`driverAgeBands` / `vehicleAgeBands`) that covers
 * the age (`fromAge <= age <= toAge`); no band, or an unknown age, gives 1.
 *
 * This is a simulation, not a real tariff, and it is intentionally NOT shown to customers: the UI
 * only shows the final price. See docs/adr/0005-simulated-price-rule-age-bands.md.
 */
export function simulatePrice(
  basePrice: number,
  driverAge: number | null,
  vehicleAge: number | null,
  country: Pick<Country, 'driverAgeBands' | 'vehicleAgeBands'>,
): number {
  return Math.round(
    basePrice *
      factorFor(driverAge, country.driverAgeBands) *
      factorFor(vehicleAge, country.vehicleAgeBands),
  );
}

import { Step1Values } from '../../../core/session/quote-session.store';
import { ageOn } from '../../quote-form/validation/named-rules';

export interface Ages {
  driverAge: number | null;
  vehicleAge: number | null;
}

/**
 * Driver age (whole years on `today`) from `birthDate` (YYYY-MM-DD) and vehicle age
 * (`today.getFullYear() - vehicleYear`, never below 0) from `vehicleYear`.
 * Invalid or missing values give null.
 */
export function agesFromStep1(values: Step1Values, today: Date): Ages {
  const birthDate = values['birthDate'];
  const vehicleYear = values['vehicleYear'];
  const driverAge = typeof birthDate === 'string' ? ageOn(birthDate.trim(), today) : null;
  const year =
    typeof vehicleYear === 'string' && /^\d{4}$/.test(vehicleYear.trim())
      ? Number(vehicleYear.trim())
      : null;
  return {
    driverAge,
    vehicleAge: year === null ? null : Math.max(0, today.getFullYear() - year),
  };
}

import { Country } from '../../../core/country/country.model';

/** Formats a whole-unit amount in the country's currency, no decimals, e.g. "$ 145.000 / mes". */
export function formatPrice(
  amount: number,
  country: Pick<Country, 'currency' | 'numberLocale'>,
): string {
  const formatted = new Intl.NumberFormat(country.numberLocale, {
    style: 'currency',
    currency: country.currency,
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(amount);
  return `${formatted} / mes`;
}

