/** Strapi DTO types — mirror cms/src/api/plan (see specs/003-us-02-plan-list/contracts/plans-api.md). */
export interface PlanItemDto {
  id?: number;
  text: string;
}

export interface PlanDto {
  id: number;
  documentId: string;
  name: string;
  shortDescription: string;
  basePrice: number | null;
  order: number | null;
  recommended: boolean | null;
  active: boolean | null;
  coverages?: PlanItemDto[] | null;
  benefits?: PlanItemDto[] | null;
}

export interface PlansResponseDto {
  data: PlanDto[];
}

/** App model. `id` is the Strapi documentId. */
export interface Plan {
  id: string;
  name: string;
  shortDescription: string;
  /** Whole monthly units of the country's currency, before the age factors. */
  basePrice: number;
  coverages: string[];
  benefits: string[];
  /** True only for the first recommended plan in order. */
  highlighted: boolean;
}

/** View model: a plan with its simulated price for the current person and vehicle. */
export interface PlanOffer {
  plan: Plan;
  finalPrice: number;
  formattedPrice: string;
}

import { Plan, PlanDto, PlanItemDto } from './plan.model';

function mapItems(items: PlanItemDto[] | null | undefined): string[] {
  return (items ?? []).map((item) => item.text).filter((text) => typeof text === 'string' && text !== '');
}

function isValidBasePrice(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value) && value >= 0;
}

/**
 * Keeps the API order (a defensive stable sort by `order` too), drops plans with an invalid
 * `basePrice`, and highlights only the first recommended one.
 */
export function mapPlans(dtos: PlanDto[]): Plan[] {
  const sorted = dtos
    .map((dto, index) => ({ dto, index }))
    .sort((a, b) => (a.dto.order ?? Infinity) - (b.dto.order ?? Infinity) || a.index - b.index)
    .map(({ dto }) => dto);

  let highlightTaken = false;
  const plans: Plan[] = [];
  for (const dto of sorted) {
    if (!isValidBasePrice(dto.basePrice)) continue;
    const highlighted = dto.recommended === true && !highlightTaken;
    if (highlighted) highlightTaken = true;
    plans.push({
      id: dto.documentId,
      name: dto.name,
      shortDescription: dto.shortDescription,
      basePrice: dto.basePrice,
      coverages: mapItems(dto.coverages),
      benefits: mapItems(dto.benefits),
      highlighted,
    });
  }
  return plans;
}

import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable, map } from 'rxjs';
import { mapPlans } from './plan.mapper';
import { Plan, PlansResponseDto } from './plan.model';

@Injectable({ providedIn: 'root' })
export class PlanService {
  private readonly http = inject(HttpClient);

  /** Active, published plans of the country, in CMS order. */
  load(countryCode: string): Observable<Plan[]> {
    const params = new HttpParams()
      .set('filters[country][code][$eq]', countryCode.toUpperCase())
      .set('filters[active][$eq]', 'true')
      .set('sort', 'order:asc')
      .set('populate[coverages]', 'true')
      .set('populate[benefits]', 'true')
      .set('pagination[pageSize]', '100');
    return this.http
      .get<PlansResponseDto>('/api/plans', { params })
      .pipe(map((response) => mapPlans(response.data)));
  }
}

import { mapPlans } from './plan.mapper';
import { PlanDto } from './plan.model';

function dto(overrides: Partial<PlanDto> & { documentId: string }): PlanDto {
  return {
    id: 1,
    name: overrides.documentId,
    shortDescription: 'Desc',
    basePrice: 100000,
    order: 1,
    recommended: false,
    active: true,
    coverages: [],
    benefits: [],
    ...overrides,
  };
}

describe('US-02 · FR-002 / FR-003 plan mapper', () => {
  it('highlights only the first recommended plan, keeping the order', () => {
    const plans = mapPlans([
      dto({ documentId: 'a', order: 1 }),
      dto({ documentId: 'b', order: 2, recommended: true }),
      dto({ documentId: 'c', order: 3, recommended: true }),
    ]);
    expect(plans.map((p) => p.id)).toEqual(['a', 'b', 'c']);
    expect(plans.map((p) => p.highlighted)).toEqual([false, true, false]);
  });

  it('sorts defensively by order', () => {
    const plans = mapPlans([dto({ documentId: 'late', order: 2 }), dto({ documentId: 'early', order: 1 })]);
    expect(plans.map((p) => p.id)).toEqual(['early', 'late']);
  });

  it('maps coverages and benefits to text; null or missing lists become []', () => {
    const [full, empty] = mapPlans([
      dto({
        documentId: 'a',
        coverages: [{ id: 1, text: 'Grúa' }],
        benefits: [{ id: 2, text: 'Asistencia' }],
      }),
      dto({ documentId: 'b', order: 2, coverages: null, benefits: undefined }),
    ]);
    expect(full.coverages).toEqual(['Grúa']);
    expect(full.benefits).toEqual(['Asistencia']);
    expect(empty.coverages).toEqual([]);
    expect(empty.benefits).toEqual([]);
  });

  it('drops a plan whose basePrice is missing, negative or not finite', () => {
    const plans = mapPlans([
      dto({ documentId: 'ok', order: 1, basePrice: 0 }),
      dto({ documentId: 'null', order: 2, basePrice: null }),
      dto({ documentId: 'neg', order: 3, basePrice: -1 }),
      dto({ documentId: 'nan', order: 4, basePrice: Number.NaN }),
    ]);
    expect(plans.map((p) => p.id)).toEqual(['ok']);
  });
});

